// What a model costs at its vendor's list price, by the name a request gives
// it, so a graph that meets a model for the first time can weigh what it
// spent. The table is data, regenerated by bin/prices.ts from OpenRouter's
// public listing; a `price` on the model's own row is what a graph weighs at.

import table from './prices.json' with { type: 'json' }
import type { Price } from './vocab.ts'

let PRICES: Record<string, Price> = table.prices

// What a name may carry beyond the model's own: a context window in brackets
// (`claude-opus-4-8[1m]`), then a release date (`claude-haiku-4-5-20251001`,
// `gpt-4o-2024-08-06`).
let EXTRA = [/\[[^\]]*\]$/, /-\d{8}$/, /-\d{4}-\d{2}-\d{2}$/]

/**
 * The list price of the model a request names, if the table holds it.
 *
 * ```ts
 * import { listPrice } from '@yaks/model'
 * import { assertEquals } from '@std/assert'
 *
 * assertEquals(listPrice('claude-haiku-4-5-20251001'), listPrice('claude-haiku-4-5'))
 * assertEquals(listPrice('no-such-model'), undefined)
 * ```
 */
export let listPrice = (name: string): Price | undefined => {
  let at = name
  for (let extra of [/^/, ...EXTRA]) {
    at = at.replace(extra, '')
    if (Object.hasOwn(PRICES, at)) return PRICES[at]
  }
  return undefined
}
